pages.append(section('ปัญหาที่ควรแก้ก่อนส่งมอบ', '''<h3><span class="tag">QA-01 · P2</span> รายงานประชุมระบุ 2 หน้า แต่ A4 ได้ 3 หน้า</h3><p><b>ทำซ้ำ:</b> admin → ดาวน์โหลดข้อมูล → ดูตัวอย่างรายงานก่อนพิมพ์ → พิมพ์ A4 ที่ scale ปกติ ด้วยข้อมูล demo และรอบทดลอง QA<br><b>พบ:</b> ส่วน “ขอบเขตและการอ่านผล” แยกไปหน้า 2 และเนื้อหาส่วนประชุมไปหน้า 3<br><b>คาดหวัง:</b> ตรงกับคำสัญญา 2 หน้า หรือเปลี่ยนข้อความเป็นจำนวนหน้าตามข้อมูล<br><b>แนวทาง:</b> ปรับพื้นที่หน้าแรกและ page-break พร้อมทดสอบข้อมูลยาว ไทย/อังกฤษ และ fonts โหลดครบ<br><b>เกณฑ์ผ่าน:</b> PDF A4 อ่านครบ ไม่ตัดแถว และเลขหน้าตรงกับจำนวนจริง</p>'''+evidence('meeting-extra-page.png','หลักฐาน PDF รอบ A4: หน้าสุดท้ายเป็นหน้า 3')+'''<p class="small">ไฟล์ต้นฉบับ: <a href="application-meeting-report.pdf">application-meeting-report.pdf</a> · ตรวจซ้ำ preferCSSPageSize ใน application-meeting-report-css.pdf</p>'''))
pages.append(section('รายละเอียดที่ทำให้ผู้ใช้สับสน', '''<h3><span class="tag">QA-02 · P3</span> สรุป validation รวมข้อความตัวเลือกเข้ากับชื่อช่อง</h3><p><b>ทำซ้ำ:</b> รอบทดลองใหม่ → กดสร้างทั้งที่ยังกรอกไม่ครบ<br><b>พบ:</b> ชื่อ error เช่น “สถานที่เลือกสถานที่” และ “ผู้ปฏิบัติงานเลือกผู้ปฏิบัติงาน” อ่านซ้ำและไม่ใช่ชื่อช่องล้วน<br><b>คาดหวัง:</b> ชื่อช่องสั้น + ข้อความแก้ไขที่ตรงกับชนิดข้อมูล<br><b>แก้:</b> ใช้ label text ที่แยกจาก option text; ทดสอบคลิกลิงก์ error แล้ว focus ช่องที่ถูกต้อง</p><h3><span class="tag">QA-03 · P3</span> ข้อความสำเร็จ online สื่อว่ายังรอ sync</h3><p><b>ทำซ้ำ:</b> admin → ตั้งค่าห้องแล็บ → เพิ่มผู้ปฏิบัติงานขณะ online<br><b>พบ:</b> รายการใหม่แสดงแล้วและมี toast สำเร็จ แต่ข้อความในฟอร์มยังว่า “บันทึกไว้แล้ว ระบบจะซิงก์อัตโนมัติ”<br><b>คาดหวัง:</b> แยก “บันทึกบนเซิร์ฟเวอร์แล้ว” กับ “เก็บในอุปกรณ์ รอส่ง” ให้สอดคล้องกัน<br><b>เกณฑ์ผ่าน:</b> online / offline / syncing / rejected แสดงสถานะเดียวที่ไม่ขัดกัน</p><h3><span class="tag">QA-04 · ต้องประเมินความเสี่ยงก่อน release</span> dependency audit มีรายการระดับ high</h3><p>npm audit รายงาน 9 packages: high 6 และ moderate 3 รวม vite, happy-dom, js-yaml และเครื่องมือทดสอบ/สร้างโค้ด ส่วนใหญ่เป็น development toolchain ไม่ใช่หลักฐานว่าเว็บ production ถูกโจมตีได้</p><p><b>การดำเนินการ:</b> ตรวจ dependency path และ advisory ที่เกี่ยวข้อง อัปเดต patch ที่แก้ได้ แล้ว build/test ซ้ำ ห้ามสรุป production exploit จากระดับ severity เพียงอย่างเดียว</p><div class="note">ยังไม่ได้แก้ source code ในรอบนี้ เพื่อคงสภาพที่ใช้ประเมินไว้ให้ตรวจซ้ำได้</div>'''))
pages.append(section('สิ่งที่ทำได้ดี และความเสี่ยงที่ต้องวางแผน', '''<h3>จุดแข็งที่ยืนยันจากการใช้งาน</h3><ul><li>แยก member/admin และ guest ชัดเจน ทั้ง UI และ API ที่ตรวจ</li><li>บัญชี member ที่ไม่ผูกผู้ปฏิบัติงานมีคำอธิบายและหยุดการบันทึก</li><li>มี validation summary, required fields, focus และข้อความแจ้งผลการทำงาน</li><li>ข้อมูลที่ยังไม่ครบใน dashboard แสดงคำเตือน แทนการตีความว่าเป็นศูนย์</li><li>R CSV มี header 30 คอลัมน์และจำนวนคอลัมน์ตรงกันทุกแถวที่ตรวจ</li><li>งาน offline เก็บในอุปกรณ์แล้วส่งเมื่อเชื่อมต่อใหม่ และตรวจหลัง reload ได้</li></ul><h3>Rate limit และหลายผู้ใช้ในห้องแล็บ</h3><p>การสำรวจแบบถี่จากหลาย session บน IP เดียวถูกจำกัด 120 requests/นาที ผลนี้เกิดจากวิธีทดสอบ ไม่จัดเป็นบั๊กงานปกติ แต่ควร load-test รูปแบบใช้งานหลายคนหลัง NAT เดียวกันก่อนส่งมอบ เพราะแต่ละหน้าดึง API หลายรายการ</p><h3>ข้อมูลสาธิตไม่ใช่หลักฐานความถูกต้องทางวิทยาศาสตร์</h3><p>ตัวเลขการรอดและจำนวนตามระยะมีข้อมูลขาดใน seed อยู่แล้ว ระบบเตือนได้ถูกต้อง แต่ยังต้องใช้ golden dataset ที่เจ้าของงานรับรอง เทียบ numerator, denominator, วันที่, timezone และ missing/zero ทุก export ก่อนนำไปใช้สรุปงานวิจัยจริง</p><h3>สภาพแวดล้อมที่ใช้</h3><p>localhost / HTTP / APP_ENV=development / cookie secure=false เป็นค่าทดสอบ ไม่ใช่ production sign-off; ยังไม่ทดสอบ TLS, domain, SMTP, restore หรือ capacity ของเครื่องลูกค้า</p>'''))
pages.append(section('รายการปิดงานก่อนลงนามรับมอบ',table(['ลำดับ','งาน','หลักฐานที่ต้องได้'],[['1','แก้ QA-01 และ retest รายงาน','PDF 2 หน้าตามสัญญา หรือข้อความใหม่ที่อนุมัติ'],['2','ทดสอบ login จริงโดยไม่ bypass','invitation → email → password → login → reset → logout / revoke'],['3','ปิด end-to-end lifecycle','batch → lot → embryo → promotion → fish → specimen → export'],['4','ปิด approval workflow','member request → admin approve/reject → audit → readback'],['5','นำเข้าข้อมูลจริงจำลอง','v5 experiment/registry; invalid/duplicate; dry run/commit/rollback'],['6','หลายผู้ใช้และ offline conflict','ไม่สูญหาย/ซ้ำเมื่อ reconnect และ retry พร้อมกัน'],['7','Scientific acceptance','golden dataset ตรงกันระหว่างหน้าจอ CSV XLSX PDF'],['8','Production rehearsal','backup/restore, HTTPS, mail, roles, monitoring และ browser ลูกค้า']])+'''<h3>ไฟล์หลักฐาน</h3><p><a href="survey.json">survey.json</a> — สำรวจหน้าและ layout (มีรอบ rate-limit ต้องอ่านบริบท)<br><a href="flows.json">flows.json</a> — สิทธิ์ API และ first-pass flows<br><a href="deep.json">deep.json</a> — การสร้างข้อมูลและ export<br><a href="finalflows.json">finalflows.json</a> — member access, offline, import และ print recheck<br><a href="memberflow.json">memberflow.json</a> — ผล flow ฝั่ง member เพิ่มเติม</p><p>ภาพ PNG และไฟล์ export อยู่ในโฟลเดอร์เดียวกับรายงาน ทุก automationError เป็นข้อผิดพลาดของสคริปต์หรือขอบเขตที่ยังตรวจไม่สำเร็จ ไม่ได้ถูกนับเป็น product defect โดยอัตโนมัติ</p><div class="note warn"><b>คำแนะนำการส่งมอบ:</b> ใช้รายงานนี้เปิด UAT กับลูกค้าได้ แต่ยังไม่ควรลงนามว่า production-ready จนปิดรายการสำคัญด้านบนและมีผล retest แนบ</div>'''))
pages.insert(5,section('วันที่ในประวัติผลตรวจยังไม่สอดคล้องกับภาษา', '''<h3><span class="tag">QA-05 · P2</span> หน้าไทยแสดงวันที่ตาม locale ของเบราว์เซอร์</h3><p><b>ทำซ้ำ:</b> ใช้ Chromium locale en-US → เลือกภาษาไทยในแอป → ติดตามตัวอ่อน → เปิด lot → ประวัติผลตรวจที่บันทึกแล้ว<br><b>พบ:</b> วันที่แสดง “11/10/2026, 11:47:26 PM” ตามรูปแบบเดือน/วัน/ปี ทั้งที่หน้าเป็นภาษาไทยและคู่มือใช้วัน/เดือน/ปี ทำให้ผู้ใช้อาจอ่านเดือนสลับวัน<br><b>คาดหวัง:</b> ระบุ locale และ timezone ของงานวิจัยอย่างสม่ำเสมอ เช่น “10 พ.ย. 2026 23:47 (Asia/Bangkok)” หรือรูปแบบที่ลูกค้ารับรอง<br><b>แนวทาง:</b> ใช้ตัวจัดรูปแบบวันเวลาเดียวกันทุกหน้ารวม tooltip, ประวัติ, เวลาร่าง และ export<br><b>เกณฑ์ผ่าน:</b> browser en-US / th-TH และ timezone ต่างกันต้องสื่อเวลาเหตุการณ์เดียวกันอย่างไม่กำกวม ไม่เปลี่ยนค่าที่เก็บในฐานข้อมูล</p>'''+evidence('member-embryo-round.png','หน้าภาษาไทยใน browser locale เริ่มต้น en-US: ประวัติผลตรวจใช้ AM/PM')+'<p class="small">นี่เป็นความไม่สอดคล้องของการแสดงผล ไม่ได้พบหลักฐานว่าค่าวันเวลาในฐานข้อมูลถูกเปลี่ยนหรือเสียหาย</p>'))
pages.insert(6,section('ข้อมูลนำเข้าว่างและความชัดเจนของขั้นตอน', '''<h3><span class="tag">QA-06 · P3</span> draft ว่างแสดงช่วงรายการ “1–0”</h3><p><b>ทำซ้ำ:</b> นำเข้าข้อมูล → อัปโหลด experiment-template-v5.xlsx ที่ยังไม่กรอก → ตรวจไฟล์ → สร้างฉบับร่าง → ขั้นตรวจประเด็น<br><b>พบ:</b> draft มี 0 รายการและ 0 ประเด็น แต่ pagination แสดง “1–0” และผู้ใช้ยังต้องเดินต่อเพื่อทราบว่าข้อมูลไม่พร้อมนำเข้า<br><b>คาดหวัง:</b> แสดง “0 รายการ” และแจ้งว่าไม่มีแถวข้อมูลใช้งาน พร้อมทางกลับไปเลือกไฟล์ใหม่; ไม่ควรสื่อว่ามีช่วงรายการย้อนลำดับ<br><b>เกณฑ์ผ่าน:</b> empty / 1 record / หลายหน้าแสดงช่วงถูกต้อง และไฟล์ว่างไม่ทำให้ข้อมูลจริงเปลี่ยน</p><div class="note">ระบบยังกันการยืนยันนำเข้าที่ไม่พร้อมไว้ได้ จึงไม่จัดเป็นข้อมูลเสียหาย การตรวจครั้งนี้ไม่ได้ครอบคลุมการ commit และ rollback ของไฟล์ที่กรอกครบ</div>'''+evidence('import-step-2.png','หน้าตรวจประเด็นของ draft ว่าง') ))
pages=[x.replace('สร้างผ่าน admin และตรวจ validation','สร้างผ่าน admin/member และตรวจ validation').replace('เปิด worklist และทดสอบรายละเอียด','member บันทึกผล 2-cell / ALIVE สำเร็จ').replace('ดู memberflow.json สำหรับผลยืนยันรายการ','ดู closeout.json; ยังไม่ทดสอบทุกสถานะและย้อนเวลา').replace('เปิดทะเบียนและฟอร์ม; ป้องกันการบันทึกซ้ำ','member ขึ้นทะเบียนปลา; ป้องกันการบันทึกซ้ำ').replace('เปิดรายการและหน้าจัดการ','member ส่งคำร้องแก้ notes สำเร็จ').replace('ดาวน์โหลด template, inspect, สร้าง draft','template download, inspect, empty draft, review gate').replace('ดู profile และประวัติ version','ดู version / แก้ไขรายระยะ; ดาวน์โหลด CSV').replace('<a href="memberflow.json">memberflow.json</a> — ผล flow ฝั่ง member เพิ่มเติม','<a href="memberflow.json">memberflow.json</a> — สร้างรอบทดลอง ปลา และส่งคำร้อง<br><a href="closeout.json">closeout.json</a> — ยืนยันผลตัวอ่อน ภาษา มือถือ 320px และ import gate<br><a href="approval.json">approval.json</a> — อนุมัติคำร้องและตรวจค่าที่อ่านกลับ<br><a href="dependency-audit.json">dependency-audit.json</a> / <a href="frontend-tests.log">frontend-tests.log</a> — ผล audit และ regression') for x in pages]
